# Candidate repair (B3) for TASK-BANK-014
def build_request(data):
    return {'path': '/v1/transfers', 'body': {'source': data['source'], 'destination': data['destination'], 'amount': {'value': float(data['amount_cents']) / 100.0, 'currency': data['currency']}}, 'headers': {'Idempotency-Key': data['idempotency_key']}}
